insert into policy_searches (district_id, public_policy_found, search_date, locations_checked, locations_unreachable, searched_by, notes) values ((select id from school_districts where slug = 'orange-county-public-schools'), FALSE, '2026-10-03', ARRAY['OCPS Policies Home index (all policy titles scanned for athletics, advertising, logos, facilities, photographs, fundraising)','Policy JJI Interscholastic Athletics (full text)','Policy JJ Extracurricular/Athletic Programs (keyword search and key paragraphs)','Policy KHB Advertising and Online Advertising (full text)','Policy KF Use of Facilities and School Board Property (most of text)','Policy JRD Photographs of Students (school picture contracts only)','Policy JJE Fund-Raising (opening sections)','Policy JIC Code of Student Conduct policy document (keyword search)','Policies KHC, KDA, DJG (keyword search for logo, trademark, likeness, NIL)','OCPS Style Guide Home','OCPS Media Relations Home','OCPS Advertising Sales Home','OCPS Facilities Home']::text[], ARRAY['OCPS Athletics district site (ocpsathletics.net) (could not be opened)']::text[], 'Claude (automated source research)', 'District NIL policy: Not located in the public sources reviewed as of October 4, 2026. The district athletics site is still unread.');
insert into policy_searches (district_id, public_policy_found, search_date, locations_checked, locations_unreachable, searched_by, notes) values ((select id from school_districts where slug = 'seminole-county-public-schools'), TRUE, '2026-10-04', ARRAY['SCPS Board Policy 2431.06, Name, Image, and Likeness (NIL) in Athletics (revised January 20, 2026)','SCPS Board Policy 2431, Interscholastic Athletics','SCPS Board Policy 9700.01, Advertising and Commercial Activities','SCPS Board Policy 7510 and the Facilities Use Handbook','SCPS Student Conduct and Discipline Code 2026-2027']::text[], ARRAY['Administrative Procedure 9700.01, General Advertising Guidelines (not opened)']::text[], 'Claude (automated source research)', 'SCPS Board Policy 2431.06 is a short published district NIL policy that recognizes NIL and points athletes to FHSAA bylaws and Board policies.');
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('NIL: Use of University Marks and Group Licensing (Last Updated 2/2/2024)', 'Florida State University Athletics', 'https://seminoles.com/documents/2024/12/12/NIL_-_Use_of_Marks_and_Group_Licensing.pdf', 'A', 'opened_now', 'low', 2, 'FSU page: logos and marks, uniform in content, campus facilities, team photos and video, merchandise, group licensing.', 'seminoles.com/feature/the-brand (FSU trademark licensing page) supports the logo approval rule only.', 'The seminoles.com URL returns an HTML viewer page, not the PDF, so earlier tools could not read it.', 'Opened my own Chrome tab on seminoles.com, found the PDF file the viewer page embeds (official Sidearm storage copy at https://s3.us-east-2.amazonaws.com/sidearm.nextgen.sites/fsuni.sidearmsports.com/documents/2024/12/12/NIL_-_Use_of_Marks_and_Group_Licensing.pdf) and read all 3 pages with pdf.js.', 'FSU says logos, marks and all parts of the uniform can be used in NIL only after a written agreement from Florida State Global Partnerships or the Office of Trademark Licensing. Campus facilities need written authorization from FSU, and INFLCR photos may not be monetized without written pre-approval. The document is dated 2/2/2024, before the House settlement, but is still linked from the current FSU NIL page.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'florida-state-university'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Florida State NIL FAQs: Student Athletes (Last Updated 2/2/2024)', 'Florida State University Athletics', 'https://seminoles.com/documents/download/2024/2/7/Florida_State_NIL_FAQs_-_Student_Athletes.pdf', 'E', 'opened_now', 'low', 2, 'None on current guidance. Context for agents, school name reference, INFLCR photos and international athletes.', 'Current FSU Compliance page and the February 2026 agent procedures.', 'Blocked by robots rules for the fetch tool.', 'Read all 3 pages with pdf.js from my own tab on seminoles.com (same origin).', 'A pre-House FAQ. It says athletes may identify themselves as FSU student-athletes in NIL, may not use INFLCR or FSU-provided images commercially, and that F-1 visa athletes should contact FSU Athletics Compliance first. It is no longer linked from the FSU NIL page.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'florida-state-university'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Florida State NIL FAQs: Fans, Supporters and Businesses (Fall 2024; footer says Last Updated 2/2/2024)', 'Florida State University Athletics', 'https://seminoles.com/documents/download/2024/9/19/Florida_State_NIL_FAQs_Fans_Supporters_and_Businesses_-_Fall_2024.pdf', 'E', 'opened_now', 'low', 2, 'None on current guidance. Repeats the marks, uniform and facility rule and names CLC as a third approver.', 'FSU Use of Marks PDF and The Brand page.', 'Blocked by robots rules for the fetch tool.', 'Read both pages with pdf.js from my own tab on seminoles.com (same origin).', 'A pre-House FAQ for businesses. It repeats that FSU marks and all parts of the uniform need a written agreement, here from Global Partnerships, CLC or the Office of Trademark Licensing, and that campus facilities need written authorization.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'florida-state-university'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('NIL Go Introduction for new Student-Athletes (25-slide presentation, copyright 2025)', 'Florida State University Athletics (host); content from NIL Go', 'https://seminoles.com/documents/2025/11/24/NIL_Go_New_Student-Athlete_Presentation.pdf', 'C', 'opened_now', 'none', 2, 'FSU disclosure rule ($600, NIL Go). No change.', 'FSU Compliance page (seminoles.com/sports/2017/7/4/compliance) and the national NIL Go rules already in the database.', 'The seminoles.com URL returns an HTML viewer page, not the PDF.', 'Found the embedded official storage copy (https://s3.us-east-2.amazonaws.com/sidearm.nextgen.sites/fsuni.sidearmsports.com/documents/2025/11/24/NIL_Go_New_Student-Athlete_Presentation.pdf) and read all 25 slides with pdf.js.', 'A generic NIL Go walkthrough: what to report, how to register, the six deal entry steps, deal statuses and the 14 day window after a Not Cleared result. It has no FSU-specific rule and does not state the 5 business day deadline.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'florida-state-university'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Florida State Athletics Announces Strategic NIL Partnership with The Battle''s End Collective (8/27/2025)', 'Florida State University Athletics', 'https://seminoles.com/news/2025/8/27/florida-state-athletics-announces-strategic-nil-partnership-with-the-battles-end-collective', 'B', 'opened_now', 'low', 1, 'FSU collectives rule and the two collective program entries.', NULL, 'Was read only through a summarising tool, so quotes needed confirming.', 'Opened the page in my own Chrome tab and read the raw article text.', 'Both quotes in the research file are exact. The release also says the Rising Spear Collective ''will be formally dissolved'' and that The Battle''s End will work with Legends, Seminole Boosters and the athletics department.', '2026-10-04');
