insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('INFLCR Compliance Reporting one-pager (2021)', 'Florida State University Athletics (host); INFLCR', 'https://seminoles.com/images/2021/06/IN_Compliance-Reporting_one-pager-2.pdf', 'E', 'opened_now', 'none', 1, NULL, 'Current FSU Compliance page names NIL Go.', 'Fetch tool could not open it.', 'Read the single page with pdf.js from my own tab on seminoles.com.', 'A 2021 INFLCR handout on self-reporting NIL transactions in the INFLCR app. Superseded by NIL Go.', '2026-10-04');
