insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Standard Operating Procedures: Student-Athlete Agent (Revised 02/2026)', 'Florida State University Athletics Compliance', 'https://seminoles.com/documents/2026/2/23/SOP_-_Student-Athlete-Agent.pdf', 'A', 'opened_now', 'medium', 1, 'FSU agents rules (registration, notice to Compliance, seven business days).', 'FSU Compliance page ''Agents & Advisors'' section, which may be older wording.', 'Not in the inaccessible list. Found today as the ''Athlete Agent Procedures'' link on seminoles.com/feature/nil.', 'Read both pages with pdf.js from the embedded official storage copy (https://s3.us-east-2.amazonaws.com/sidearm.nextgen.sites/fsuni.sidearmsports.com/documents/2026/2/23/SOP_-_Student-Athlete-Agent.pdf).', 'The newest FSU NIL-related document found. Agents must register with FSU every year before contacting an athlete about NIL, and must file an Athlete Representation Disclosure Form after signing an athlete. It says athletes are ''advised'' to tell Compliance before first contact, which is softer than the Compliance page wording.', '2026-10-04');
