insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Miami NIL Policy (Miami NIL Program / Guidelines page)', 'University of Miami Athletics', 'https://miamihurricanes.com/nil-guidelines/', 'E', 'opened_now', 'medium', 1, 'Miami disclosure workflow (currently empty) and every pre-House item listed in ambiguities.', NULL, 'Logged for a human to confirm whether it is still in force. No outreach is allowed in this phase.', 'Re-read the full page as raw text from my own tab. Also checked the Compliance, Current Student-Athletes, Boosters, Agents and NIL pages and ran one web search for newer Miami disclosure guidance.', 'The page is unchanged. It still says to disclose in the Opendorse app at least 48 hours before signing and cites the NCAA interim policy and May 2022 guidance. No newer public Miami disclosure guidance was found.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'university-of-miami'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('2021 Booster NIL Policy Handout (linked as ''Booster NIL Poster'')', 'University of Miami Athletics Compliance', 'https://miamihurricanes.com/documents/688da163-3d52-441d-8024-8f031b40b30d.pdf', 'E', 'opened_now', 'low', 2, 'None on current guidance. It is a July 2021 handout.', 'Miami NIL Policy page says the same things.', 'The URL returns an HTML viewer page, not the PDF.', 'Found the embedded official storage copy (https://storage.googleapis.com/miamihurricanes-com-prod/2021/07/097c2e1f-booster-nil-policy-handout.pdf) and read both pages with pdf.js.', 'A 2021 handout for boosters. It says boosters may pay athletes for NIL at fair market value for real work, deals must be disclosed by the athlete via Opendorse, and UM staff cannot facilitate meetings between athletes and boosters. It predates the House settlement.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'university-of-miami'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('From the Desk of Dan Radakovich (July 1, 2025)', 'University of Miami Athletics', 'https://miamihurricanes.com/news/2025/07/01/from-the-desk-of-dan-radakovich-40', 'B', 'opened_now', 'low', 1, 'Miami school-payments rule (revenue sharing sports) and the Canes Connection rule.', NULL, 'Was read only through a summarising tool, so wording needed confirming.', 'Fetched the page from my own tab on miamihurricanes.com and read the raw letter text.', 'Quotes confirmed. The letter names football, men''s and women''s basketball, baseball, soccer, volleyball, women''s tennis and women''s track and field as the 2025-26 revenue sharing sports, and calls Canes Connection the Official NIL Collective of Miami Athletics.', '2026-10-04');
