insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Booster Brochure 2022-23 (online version)', 'University of Miami Athletics Compliance', 'https://miamihurricanes.com/documents/0ab679f4-47fe-4df8-a13d-fb60583401df.pdf', 'E', 'still_inaccessible', 'low', 1, 'None. A 2022-23 booster brochure cannot control current NIL guidance.', 'The 2021 Booster NIL handout and the Miami NIL Policy page cover booster NIL for that period.', 'The URL returns an HTML viewer page, not the PDF.', 'Found the embedded storage copy (https://storage.googleapis.com/miamihurricanes-com-prod/2022/08/73383faa-booster-brochure-2022-23-online-version.pdf). It opens (6 pages) but the pages are images with no text layer, so the words could not be read.', 'Not read. Image-only PDF titled ''Booster Brochure 2022-23''.', '2026-10-04');
