insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('2023-24 Student-Athlete Handbook (file dated 02.05.24)', 'University of Miami Athletics', 'https://miamihurricanes.com/documents/4d38b47c-a960-4078-a7b3-f666ab68c1a8.pdf', 'E', 'opened_now', 'low', 1, 'None on current guidance. It is the only public place that lists Miami''s prohibited NIL categories, as of 2023-24.', NULL, 'Not in the inaccessible list. Found today as a link on miamihurricanes.com/current-student-athletes.', 'Read the NIL pages (29 and 30 of 72) with pdf.js from the embedded storage copy (https://storage.googleapis.com/miamihurricanes-com-prod/2024/02/ab17e5af-2023-24-sa-handbook-02.05.24.pdf).', 'A pre-House handbook. Its ''NIL Rules at-a-Glance'' says to disclose in Opendorse 48 hours ahead, bars NIL activity in University facilities, bars F-1 visa athletes from NIL in the U.S., and lists prohibited categories. It points to a full ''NIL Policy on Teamworks'', which is behind a login and was not opened.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'university-of-miami'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('USF Athletics Name, Image, and Likeness (NIL) Policy (updated 7.13.2021)', 'University of South Florida Athletics', 'https://gousfbulls.com/documents/2022/7/18/USF_NIL_Policy__Updated_7.13.2021_.pdf', 'E', 'opened_now', 'low', 2, 'None on current guidance. It is the detail behind the ''outdated'' USF policy entry.', 'USF 2022 guidelines page states the same rules.', 'Blocked by robots rules for the fetch tool. The URL also returns an HTML viewer page, not the PDF.', 'Found the embedded official storage copy (https://s3.us-east-2.amazonaws.com/sidearm.nextgen.sites/usf.sidearmsports.com/documents/2022/7/18/USF_NIL_Policy__Updated_7.13.2021_.pdf) and read both pages with pdf.js.', 'A two page 2021 policy written under Florida Statute 1006.74. It bars USF marks except through licensees or sponsors, requires a disclaimer when USF is mentioned, lists banned categories, requires disclosure through INFLCR within 5 days, and makes facility use subject to USF Athletics approval. It bars USF-affiliated pay, so it is out of date after the House settlement.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'university-of-south-florida'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Name, Images, Likeness Guidelines (2022 page)', 'University of South Florida Athletics', 'https://gousfbulls.com/sports/2022/7/18/name-images-likeness-guidelines', 'E', 'opened_now', 'medium', 1, 'USF policy status (outdated).', 'USF 2021 policy PDF, now read.', 'Logged for a human to ask USF whether it is still in force. No outreach is allowed in this phase.', 'Re-fetched from my own tab. The page is still online and still links the NCAA interim policy, the May 2022 NCAA guidance and the 2021 USF policy PDF. Also checked the current NIL page, compliance home page and staff directory and ran one web search for newer USF NIL rules.', 'Unchanged pre-House page. No newer USF NIL rules or NIL Go disclosure instructions were found on gousfbulls.com.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'university-of-south-florida'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('USF Athletics Staff Directory', 'University of South Florida Athletics', 'https://gousfbulls.com/staff-directory', 'B', 'opened_now', 'low', 1, 'USF NIL and compliance contacts.', 'USF NIL landing page (2025) lists two of the same people.', 'Logged for a human to confirm contacts.', 'Fetched from my own tab and read the raw directory text.', 'Lists Brendan Armitage (Senior Associate Athletics Director / Compliance, (813) 974-6885, [email on the official page]), Mercedes Sapp (Director of NIL Engagement), Ansel Triebe-Pay (shown here as ''Director of NIL'') and Larry Antonucci (Director of NIL Community Development).', '2026-10-04');
