insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('USF Athletics Expands INFLCR Partnership, Adding The Bull Market Exchange (September 2, 2022)', 'University of South Florida Athletics', 'https://gousfbulls.com/news/2022/9/2/baseball-usf-athletics-expands-inflcr-partnership-adding-the-bull-market-exchange', 'E', 'opened_now', 'low', 1, 'Whether the INFLCR exchange is a current USF program.', NULL, 'Not opened in the first pass.', 'Fetched from my own tab and read the raw release text.', 'A 2022 release launching the Bull Market Exchange on INFLCR. It says neither USF Athletics nor INFLCR takes part in negotiations. Nothing on the current USF site confirms the exchange is still live.', '2026-10-04');
