insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('UCF Athletics Staff Directory', 'UCF Athletics', 'https://ucfknights.com/staff-directory', 'B', 'opened_now', 'low', 2, 'UCF NIL, revenue share and compliance contacts.', 'ucfknights.com/compliance prints the office phone and email.', 'WebFetch permission request timed out in the first pass.', 'Fetched the directory and the Compliance and Brand Partnerships department pages from my own tab on ucfknights.com and read the raw text.', 'All four named contacts in the research file match the directory. Ainsleigh Wall has no email listed. The directory also lists Jordan Litten, Director, Football Advancement, NIL Operations & Athlete Branding.', '2026-10-04');
