insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('UCF Policy 2-207.1 Licensing and Use of University-owned Copyrighted Materials and Trademarks (effective 7/23/2021)', 'University of Central Florida', 'https://policies.ucf.edu/documents/2-207.pdf', 'B', 'opened_now', 'low', 1, 'UCF logos and marks rule.', 'UCF Brand Governance page (ucf.edu/brand/brand-governance).', 'Carried from earlier research without being re-opened, so wording needed confirming.', 'Read the 10 page PDF with pdf.js from my own tab on policies.ucf.edu (same origin).', 'No mention of NIL or student-athletes. Commercial merchandise use of UCF marks goes through Collegiate Licensing Company. Other commercial use of UCF Athletics Marks needs prior written permission from UCF Athletics with the General Counsel''s Office. The Business Services contact is the Auxiliary Services Manager, 407.823.3539.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'university-of-central-florida'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('FAU Student-Athlete Handbook 2026-27', 'Florida Atlantic University Athletics', 'https://fausports.com/documents/2026/7/1/SA_H_26-27_remediated.pdf', 'A', 'opened_now', 'none', 1, 'All FAU handbook rules (NIL allowed, disclosure, marks, facilities, gear, agents, staff involvement, international).', NULL, 'Flagged for a manual check of page 31 wording and bullet layout.', 'Opened in my own Chrome tab and read with pdf.js from the public file link shown on the document page. Read the full NIL section on page 31 and searched all 45 pages for NIL, Opendorse, INFLCR, Teamworks, NIL Go, disclosure and collective.', 'Wording matches the research file. The NIL section is half a page on page 31 and does not name the disclosure platform or a deadline. The only other NIL mentions are a media rule on page 37 and an Opendorse branding tip on page 39.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'florida-atlantic-university'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('FAU Agent/Advisor Registration Application', 'Florida Atlantic University Compliance Office', 'https://fausports.com/documents/2023/7/17/Agent-Advisor_Registration_Application__1_.pdf', 'B', 'opened_now', 'medium', 2, 'FAU agents rule: who receives agent and NIL service provider registrations.', 'FAU Agents page (s3) names the same person.', 'Not opened in the first pass.', 'Opened in my own Chrome tab and read with pdf.js from the public file link shown on the document page. Read all 5 pages.', 'The form covers athlete agents, financial advisors, marketing reps and ''Name/Image/Likeness Professional Service Provider''. It says to return it to John Stephenson, Compliance Office, who is not on the current staff directory. It also says an NIL representation contract may not run past the athlete''s time in a college athletic program.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'florida-atlantic-university'), NULL);
