insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('FIU 2026-2027 Student-Athlete Handbook', 'FIU Athletics', 'https://fiusports.com/documents/2026/8/24/Student_Handbook_2026-2027.pdf', 'A', 'opened_now', 'none', 1, 'FIU disclosure, deal review, prohibited categories, contract length, agents and team activities rules.', 'FIU Policy 910.001 (s3) for the policy text it repeats.', 'Flagged for a manual check of pages 98 to 101.', 'Opened in my own Chrome tab and read with pdf.js from the public file link shown on the document page. Read pages 98 to 101 in full and searched all 108 pages for NIL, INFLCR, NIL Go, agent, collective and international.', 'Wording matches the research file. The handbook names the INFLCR app for disclosure before signing, a $10,000 second review, a 10 day fix window, six banned categories and a contract length limit, then restates the national NIL Go steps. The agents section says registration forms are on fiusports.com under the Athletics Compliance tab.', '2026-10-04');
