insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('FIU Policy 910.001 Student-Athlete Name, Image, and Likeness (PDF)', 'Florida International University', 'https://policies.fiu.edu/files/910.001', 'A', 'opened_now', 'low', 1, 'All FIU rules that cite Policy 910.001, and whether a newer version exists.', 'FIU 2026-2027 Student-Athlete Handbook (s2) repeats the policy statement.', 'Flagged to confirm revision history and the rescinded procedure page.', 'Opened in my own Chrome tab and read with pdf.js from the public file link shown on the document page. Read all 4 pages. Also read the policy library page and the library''s A to Z listing.', 'History confirmed: effective July 1, 2021, last revised May 8, 2023, reviewed with no updates February 9, 2024. The FIU policy library lists only this one NIL policy, so no newer version was located. The policy still cites the old Florida NIL law and the NCAA interim policy.', '2026-10-04');
