insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('FIU Procedure 910.001a Student-Athlete Name, Image, and Likeness', 'Florida International University', 'https://policies.fiu.edu/files/910.001a', 'E', 'not_found_404', 'low', 1, 'FIU disclosure and deal review steps.', 'FIU 2026-2027 Student-Athlete Handbook (s2) carries the working steps.', 'Marked temporarily rescinded. No text published.', 'Read page 4 of the policy PDF, which is the procedure page. Checked the library listing and tried the matching file address in my own Chrome tab.', 'No procedure text is published. Page 4 of the policy PDF says the procedure dated August 16, 2022 was temporarily rescinded after the Florida NIL law changed on February 16, 2023, pending a revised procedure. That page shows a last revision date of March 15, 2023. No replacement procedure is listed in the policy library.', '2026-10-04');
