insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('UNF Name, Image, Likeness Reference Guide (image)', 'University of North Florida Athletics', 'https://unfospreys.com/sports/2023/11/30/nil-fact-sheet-2025-26', 'A', 'opened_now', 'none', 1, 'All UNF rules that cite the Reference Guide.', 'UNF Policy 5.0110P and the 2026-27 Student-Athlete Handbook now support the same rules in text.', 'Text is inside an image and was read by eye.', 'Opened the image file in my own Chrome tab at full width and read all three screens of it.', 'Every quote in the research file matches the image. The guide prints no date. The ''on call'' line sits under ''Impermissible for Institutions'', so it limits what UNF may allow, not a separate athlete rule.', '2026-10-04');
