insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('2026-27 UNF Student-Athlete Handbook', 'University of North Florida Athletics', 'https://www.unf.edu/athletics/student-handbook/', 'A', 'opened_now', 'medium', 2, 'UNF logos, uniforms, facilities, agents, international athletes and disclosure rules.', NULL, 'Not opened in the first pass.', 'Opened in my own Chrome tab. Read the index and scanned all eight handbook pages. Read the Name, Image, Likeness and Agents parts in full.', 'The handbook has an NIL section on its NCAA Eligibility and Participation page. It adds rules the one page guide lacks: no UNF logos, marks or uniforms without written permission through an NIL Logo Request workflow, agents must also register with the UNF Compliance Office, and F-1 athletes need guidance and approval before any NIL activity.', '2026-10-04');
