insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('Name, Image, and Likeness Policy v.5', 'Stetson University (NAVEX One policy library)', 'https://stetsonuniversity.navexone.com/content/docview/?docid=303&public=true', 'A', 'opened_now', 'low', 2, 'All Stetson NIL rules: disclosure recipient, deadline and threshold, agents, marks, facilities, prohibited deals, international athletes, penalties.', NULL, 'Embedded Word viewer would not render reliably and robots.txt blocked the fetch tool. Only about one of six pages was read.', 'Opened the public viewer in my own Chrome tab. The Word viewer is a cross-origin frame, so text is not in the DOM and scroll input did not reach it. Made the public viewer frame tall with page styling so all pages rendered, then read every page by eye from screenshots. No login, no download, no access control bypassed.', 'All six pages read in full (visual). Athletes must report non-school NIL deals of $600 or more to NIL GO within five business days. The policy covers agents, marks, sponsor conflicts, facilities, international athletes and withholding of services for late disclosure. It does not address boosters, uniforms or product categories.', '2026-10-04');
