insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('SCPS Board Policy Manual: Policy 2431.06 Name, Image, and Likeness (NIL) in Athletics', 'School Board of Seminole County (Neola policy manual)', 'https://go.neola.com/semi-fl/policy/policy-manual/po2431.06', 'A', 'opened_now', 'high', 1, 'Seminole High School page and the Seminole County district record: whether the district has a published NIL policy.', NULL, 'Board policy manual (individual policies) could not be opened.', 'Opened the public policy manual in my own Chrome tab and read the policy page text in full. Also read Policy 2431 Interscholastic Athletics and Policy 9700.01 Advertising and Commercial Activities.', 'The district has a board policy named Name, Image, and Likeness (NIL) in Athletics, revised January 20, 2026. It says the Board recognizes the right of high school athletes to use and benefit from their NIL. It says athletes must still follow Florida law, State Board rules, Board policies and FHSAA bylaws, and that failing to do so may affect amateur status.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'seminole-high-school-sanford'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('SCPS Board Policy 9700.01 Advertising and Commercial Activities', 'School Board of Seminole County (Neola policy manual)', 'https://go.neola.com/semi-fl/policy/policy-manual/po9700.01', 'A', 'opened_now', 'medium', 1, 'Seminole High School page: use of the district name, students and facilities in commercial advertising, and what school sponsors may receive.', NULL, 'Part of the board policy manual that could not be opened. Counted under the manual entry.', 'Opened in my own Chrome tab and read in full.', 'The Board says its name, students, staff members and District facilities shall not be used for commercial advertising without approval of the Board or its designee. Schools may recognize business sponsors with temporary signage at athletic facilities. The policy does not mention NIL or student-athletes by name.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'seminole-high-school-sanford'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('SCPS Student Conduct and Discipline Code 2026-2027', 'Seminole County Public Schools', 'https://files.smartsites.parentsquare.com/6662/2026-2027_student_conduct_and_discipline_code.pdf', 'B', 'opened_now', 'low', 1, 'Seminole High School page: any conduct-code rule on NIL, amateurism or athlete conduct.', 'SCPS Policy 2431.06 is the district NIL statement.', 'Could not be opened.', 'Followed the public link from the SCPS Policies & Procedures page to the 2026-27 PDF. Opened in my own Chrome tab and read the text with pdf.js from the same origin. All 59 pages searched. An older file name found by search returned 403.', 'No NIL content. Zero hits for NIL, likeness, amateur, FHSAA or logo in 59 pages. Board approved 7/28/2026. It covers general student discipline and says extracurricular participation can be limited for discipline.', '2026-10-04');
insert into source_access_pages (issue_id, institution_id, district_id) values ((select max(id) from source_access_issues), (select id from institutions where slug = 'seminole-high-school-sanford'), NULL);
insert into source_access_issues (title, organization, url, class, status, risk, occurrences, claim_affected, other_support, why_unopened, retry, finding, triaged_on) values ('SCPS Policy 7510 Use of District Facilities and Facilities Use Handbook (Rev. 05-2024)', 'Seminole County Public Schools', 'https://go.neola.com/semi-fl/policy/policy-manual/po7510', 'B', 'opened_now', 'low', 1, 'Seminole High School page: facility-use rule for NIL shoots.', NULL, 'Could not be opened.', 'Opened Policy 7510 in my own Chrome tab and searched it. Read the 11-page handbook with pdf.js from https://files.smartsites.parentsquare.com/6662/scps_2024_facilities_use_handbook_rev_05-2024.pdf.', 'No NIL content and no rule on commercial filming or photography. Outside use of district facilities is requested online through Facilitron and follows Policy 7510. Non-government community users are Category IV and pay facility use, utility and personnel fees.', '2026-10-04');
