insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'FSU requires agents to register with FSU (online Agent Registration Form) before contacting an athlete about NIL.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'FSU says NIL uses of FSU logos or marks must go through the Office of Trademark Licensing and FSU''s Global Partnerships team.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'The Battle''s End is FSU''s official NIL collective since August 27, 2025, and Rising Spear was to be dissolved (read by extraction, confirm wording).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'FSU''s compliance page states the NIL Go rule: $600 or more, within 5 business days.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'Named NIL contacts and emails on seminoles.com/feature/nil are still current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'Street address 403 Stadium Drive West, Tallahassee, FL 32304 came from the staff directory through a summarising tool.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'The 2021 page ''Florida State NIL Guidelines'' (seminoles.com/news/2021/6/29/nilinfo) is still online. It says deals must be reported in the INFLCR app, that campus facilities need written authorization, and that international athletes should consult the FSU Center for Global Engagement. It predates the House settlement and is not treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'seminoles.com/feature/nil is undated, cites 2023 sales figures, and does not mention The Battle''s End or revenue sharing.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'The Brand page is undated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'The staff directory also lists a phone number for the NIL Coordinator. It was read by extraction only and was left out.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'The site menu does not label gender for every sport, so the sports lists should be checked. Track & Field (indoor and outdoor) was left out because the menu gives no gender.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Use of Marks and Group Licensing PDF is dated 2/2/2024. It is still linked from the current FSU NIL page, so it is treated as FSU''s standing guidance, but a reviewer should decide whether to show its date on the page.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The NIL Go presentation is a generic NIL Go deck. It adds no FSU rule and does not state the 5 business day deadline, which comes from the FSU Compliance page.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The two 2024 FAQ PDFs are pre-House and are not linked from the current NIL page. They were not used for rules. They say athletes may identify as FSU student-athletes, that INFLCR or FSU-provided images are not approved for commercial use, and that F-1 visa athletes should contact FSU Athletics Compliance. They list [email on the official page] as the contact, which was not confirmed as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Fans FAQ adds CLC as a third body that can give written agreement for marks. The athlete-facing marks PDF names only Global Partnerships and the Office of Trademark Licensing.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: seminoles.com document URLs return an HTML viewer page. The PDF text was read from the official storage copy that the viewer page embeds. Nothing was downloaded to disk.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing agents rule 1 (register with FSU) is incomplete. The February 2026 procedures add that registration is annual, that it must be done ''within seven (7) business days of first contact'', and that agents must file an Athlete Representation Disclosure Form after signing an athlete.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing agents rule 2 says the athlete ''must tell'' Compliance before first contact, quoting the Compliance web page (''provided the student-athlete notifies''). The February 2026 procedures say ''It is advised that'' the athlete notify Compliance. The two official sources differ. The newer document should control, or the conflict should be shown.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing agents rule 2 says agents who write to athletes must send a copy to Compliance. The February 2026 procedures instead say agents ''must notify FSU Athletics Compliance Office prior to initial contact occurring''.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing collectives rule can move from read_method extraction to raw_text. Both quotes are exact. Change ''would be dissolved'' to FSU''s wording ''will be formally dissolved''. The release text says ''announced Monday'' although it is dated 8/27/2025.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found items ''current facility-use rule for NIL shoots'' and ''current rule on wearing the uniform in NIL content'' are now answered by the Use of Marks PDF, with the caveat that it is dated 2/2/2024.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: The existing logos rule names Trademark Licensing and Global Partnerships. The Use of Marks PDF confirms this and adds that the uniform counts as a mark.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing own-merchandise rule (group licensing royalties) is supported by page 3 of the Use of Marks PDF. That page names the Compass App, OneTeam, The Brandr Group and The NIL Store, which may be out of date.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'conflict', 'The 2021 NIL Guidelines page says to report deals in the INFLCR app. The current Compliance page says to disclose in NIL Go. The Compliance page is the current one.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'not_found', 'FSU revenue-sharing statement on seminoles.com');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'not_found', 'current facility-use rule for NIL shoots');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'not_found', 'current FSU list of prohibited NIL categories');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'not_found', 'current international athlete NIL guidance');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'not_found', 'current rule on wearing the uniform in NIL content (may be in the unopened marks PDF)');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'claim', 'Miami''s only published NIL policy page predates the House settlement and still says to disclose in the Opendorse app at least 48 hours before signing. Do not present this as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'claim', 'Canes Connection is the official NIL collective of Miami Athletics (2023 release, restated July 1, 2025).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'claim', 'Miami marks and logos may be used in NIL only through agreements with approved licensees or sponsors (Legends Global, Fanatics Licensing Management).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'claim', 'Miami AD letter of July 1, 2025 says named sports take part in revenue sharing for 2025-26 (read by extraction).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'claim', 'Compliance contact: [email on the official page], 305-284-2692.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'The ''Miami NIL Policy'' page is undated and pre-House. It says: disclose all NIL activities through the Opendorse app at least 48 hours before execution; university employees and athletics support entities may not pay athletes for NIL; prohibited categories are in a department policy given to athletes (the list is not published); agents must be registered with the State of Florida; contracts may not run past eligibility; international athletes need approval from International Student and Scholar Services for off-campus employment; no use of Miami trademarks, logos, marks or colors without written approval. None of this is treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'The NIL page names both INFLCR (Miami Exchange) and the policy page names Opendorse. It is unclear which platform Miami uses today.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'The NIL page and Agents page are undated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'Street address was not read on an official page and is left empty.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'Sports with no gender label in the staff directory (Golf, Rowing, Swimming & Diving, Track & Field/Cross Country) were left out of the sports lists.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 re-check: Current Miami disclosure platform: Not located in the public sources reviewed as of October 4, 2026. Pages checked today: NIL page, NIL Policy page, Compliance, Current Student-Athletes, Prospective Student-Athletes, Boosters, Agents, the July 1, 2025 AD letter, plus one web search. None mention NIL Go.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 re-check: The 2023-24 handbook says athletes are ''also responsible for the information in the NIL Policy available on Teamworks''. Teamworks is behind a login and was not opened. Miami''s working NIL policy may live there and not on the public site.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 re-check: Historical only, from the 2023-24 handbook: disclose via Opendorse 48 hours ahead; send agent disclosures to [email on the official page]; no University logos unless partnered with a University sponsor; NIL activities ''cannot take place in University facilities''; no use of content provided by UM staff; F-1 visa athletes ''may NOT participate in NIL activities while in the U.S.''; prohibited categories include sports gambling, assault weapons, cannabis, illegal drugs, pornography, other college sports teams and tobacco. Several of these conflict with post-House practice and must not be shown as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 re-check: Historical only, from the 2021 booster handout: ''University of Miami staff members cannot facilitate meetings between student-athletes and boosters.''');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Booster Brochure 2022-23 is an image-only PDF and could not be read as text. It is a 2022-23 document and would not control current guidance.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 re-check: Miami''s NIL landing page still names INFLCR (Miami Exchange) while the policy page and handbook name Opendorse. The conflict stands.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing school-payments rule can move from extraction to raw_text. Replace the partial quote ''will participate in revenue sharing'' with the full sentence naming the sports.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 correction: Existing collectives rule: the s5 quote is exact. It can be marked raw_text.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 correction: manual_review item for miamihurricanes.com/compliance-forms/ should be dropped. The page returns 404.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 correction: The document logged as ''Booster NIL Poster'' is titled ''2021 Booster NIL Policy Handout''. It is a 2021 document and must not be used as current booster guidance.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found item ''published list of Miami prohibited NIL categories'' has a partial historical answer: the 2023-24 handbook lists categories. It is pre-House and points to a fuller list in a Teamworks policy that is not public.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'conflict', 'The Miami NIL Policy page says university-linked entities may not pay athletes for NIL. The July 1, 2025 AD letter says athletics departments can now share revenue directly. The policy page has not been updated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'manual_review', 'Class F, none risk: Compliance Forms page (https://miamihurricanes.com/compliance-forms/). Not opened in the first pass.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'manual_review', 'Class E, low risk: Booster Brochure 2022-23 (online version) (https://miamihurricanes.com/documents/0ab679f4-47fe-4df8-a13d-fb60583401df.pdf). The URL returns an HTML viewer page, not the PDF.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'manual_review', 'Class A, high risk: University of Miami NIL Policy on Teamworks. Miami''s 2023-24 Student-Athlete Handbook says athletes are also responsible for "the NIL Policy available on Teamworks". Teamworks is behind a login.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'not_found', 'current Miami disclosure instructions that mention NIL Go');
