insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'manual_review', 'Could not be opened: University of Miami NIL Policy on Teamworks (behind a login)');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'claim', 'USF''s published NIL rules (2022 guidelines page, 2021 policy PDF) predate the House settlement. Do not present them as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'claim', 'USF''s current NIL page (August 2025) lists Ansel Triebe-Pay (Director of NIL Administration) and Mercedes Sapp (Director of NIL Engagement) with emails.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'claim', 'USF launched Bulls Athletic Properties on June 20, 2025, which works with its NIL programs (read by extraction).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'claim', 'The Fowler Avenue Collective closed in April 2026 according to WUSF. This is secondary reporting, not a USF statement.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'claim', 'USF''s compliance page has no NIL content.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'The 2022 guidelines page is pre-House. It says: USF, the athletic department, staff or boosters may not pay or arrange NIL pay; USF marks, logos, green and gold colors, team photos and video and all parts of the uniform need written agreement or permission from the University (it names Kim Hill, USF''s Chief Marketing Officer); athletes may not sell or sign USF-issued gear; no NIL deals with gambling or sports wagering vendors or vendors tied to performance enhancing drugs; contracts may not run past participation at USF; agents must be licensed in Florida. None of this is treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'The 2022 page names Kim Hill as the person who grants written permission for marks. This was not confirmed as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'Page dates for USF sources were taken from the URLs.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'Street address and sports list were not read on an official page and are left empty.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'No USF statement on the status of any collective was found. The closure of the Fowler Avenue Collective comes from news reporting.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'The Bulls Athletic Properties release calls it an ''independent division''. Its exact legal form is not stated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: Historical only, from the 2021 policy PDF: athletes may mention USF but ''may not use USF''s marks'' except through contracted licensees or sponsors, under USF policy 0-215; a disclaimer is required when USF is mentioned; no deals that tie USF''s name or marks to competitors of exclusive sponsors (it names Coca-Cola and adidas) or to alcohol, tobacco, nicotine devices, marijuana, controlled substances, performance enhancing substances, sports betting, casino gambling or adult entertainment; disclose through INFLCR within 5 days; no contract past participation at USF; USF Athletics facilities need prior approval, insurance and a licensing agreement; international athletes should ask the USF Office of International Services.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The 2021 policy says USF-affiliated entities and employees ''may not compensate or cause compensation to be directed to athletes''. That reflects the repealed 2021 Florida law and is out of date after the House settlement.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: Current USF NIL rules and NIL Go disclosure instructions: Not located in the public sources reviewed as of October 4, 2026. Checked today: 2025 NIL page, What is NIL page, 2022 guidelines page, compliance home page, staff directory, 2026 brand guidelines, plus one web search. The compliance home page has no NIL links.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: Hannah Delph is listed as Assistant Athletic Director of Compliance, (813) 974-5040. Her email ran into the phone number in the page text and was left out.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The 2026 brand guidelines are current but do not address athlete NIL use of marks.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: Compliance contact for Brendan Armitage can now carry phone (813) 974-6885 and email [email on the official page], both printed in the staff directory.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: Ansel Triebe-Pay is ''Director of NIL Administration'' on the NIL page but ''Director of NIL'' in the staff directory. Keep the NIL page title and note the difference.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: Add Larry Antonucci, Director of NIL Community Development, listed in the staff directory.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: The conflict noted in the 2022 guidelines page (four days versus five days) is settled by the policy PDF, which says ''shall disclose the contract or transaction to USF through INFLCR within 5 days''. This is still outdated guidance.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: The INFLCR program entry can cite the 2022 Bull Market Exchange release, but its status stays unknown.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'conflict', 'Inside the 2022 guidelines page: the rules text says athletes must disclose ''within four days'' and the FAQ says ''Within five days of NIL agreement through the INFLCR App.''');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'not_found', 'current USF disclosure instructions that mention NIL Go');
