insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'claim', 'UCF says it fully takes part in revenue sharing and funded the maximum for 2025-26 (director letters, s4 and s5).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'claim', 'UCF says staff can connect a business directly to an athlete for outside NIL, subject to CSC/NIL Go approval (s3).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'claim', 'UCF''s former official collective, The Kingdom, was folded into the ChargeOn Fund in 2025 (s6).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'claim', 'No current UCF athlete NIL policy, disclosure form or UCF deadline was located. Do not publish one.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'claim', 'Students need written permission from University Brand and Marketing to use UCF trademarks (general rule, not NIL-specific, s8).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'The only UCF handbook with an NIL section found in earlier research is the 2021-22 edition. It names a ''COMPASS'' disclosure platform and bars staff involvement. It is outdated and was not used as a current rule.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'A 2016 UCF compliance page still online says athlete names and pictures may not be used commercially. It is pre-NIL and outdated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'A 2016 UCF agent registration page is still online. No current UCF agent rule for NIL was found, so no agent rule is recorded.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'The 2022 Icon Source marketplace announcement was not confirmed as current and is not listed as a program.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'The June 10, 2025 director letter is dated before July 1, 2025. It is used only where the December 2025 pages say the same thing or for revenue sharing start.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'Gender split of some sports (baseball, football, rowing, softball, volleyball) is inferred from the sport, not stated in the site navigation.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'The brand partnerships contact was read in earlier same-day research and not re-opened in this pass.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: Policy 2-207.1 is effective 7/23/2021. The contact for merchandise questions is an office and title, not a named person.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The policies.ucf.edu index page was scanned for athletics or name, image and likeness policies. Only 2-207.1 matched.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The remaining compliance page links go to 2016 pages, including ''Using a UCF Student-Athlete Name or Photo?'', which the research file already flags as outdated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: Staff contacts are confirmed by raw text: Brittney Anderson-Duzan ([email on the official page]), Ainsleigh Wall (no email listed) and Antwan Owens ([email on the official page]). The ambiguity that the brand partnerships contact was not re-opened can be removed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: The existing logos rule cites only the Brand Governance page. Policy 2-207.1 can be added as a second source. It names UCF Athletics and the General Counsel''s Office as approvers for commercial use of athletics marks, not only University Brand and Marketing.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: manual_review item on the compliance page links is resolved: /policy, /overview, /mission-statement and /booster-guide all still return 404.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'conflict', 'The 2021-22 handbook says UCF staff may not be involved in NIL. The December 2025 ''Get Involved'' page says staff can connect businesses to athletes. The newer page is treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'manual_review', 'Class F, none risk: UCF Compliance page sub-links: Policy, Overview, Mission Statement, Booster Guide (Coming Soon) (https://ucfknights.com/policy). Returned 404 in earlier research.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-central-florida'), NULL, NULL, 'not_found', 'Current UCF NIL policy or athlete NIL guidelines');
